from src.nodes.base import BaseNode
from src.runtime.assets import get_asset_discovery_engine, get_provider_registry, SketchfabProvider, PolyhavenProvider
from src.runtime.assets.schema import AssetQueryResult
import json

class Hou_Mcp_Asset_Discover(BaseNode):
    name = "hou_mcp_asset_discover"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("scene_plan_json",    "string", widget_type="text")
        self.add_input("asset_queries_json", "string", widget_type="text")
        self.add_input("limit_per_provider", "int",    widget_type="int",  default=20)
        self.add_output("discovery_result_json", "string")
        self.add_output("total_assets",          "int")
        self.add_output("providers_queried",     "string")
        self.add_output("query_count",           "int")
        self.add_output("discovery_ok",          "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        # Ensure default providers are registered
        reg = get_provider_registry()
        if not reg.all_providers():
            reg.register(SketchfabProvider())
            reg.register(PolyhavenProvider())

        plan_json    = inputs.get("scene_plan_json", "") or ""
        queries_json = inputs.get("asset_queries_json", "") or ""
        limit        = int(inputs.get("limit_per_provider") or 20)

        queries = []
        # Priority: wired asset_queries_json > scene_plan_json
        if queries_json.strip():
            try:
                data = json.loads(queries_json)
                queries = data if isinstance(data, list) else []
            except Exception as exc:
                self.log_error(f"Failed to parse asset_queries_json: {exc}")
                return {"discovery_result_json": "{}", "total_assets": 0,
                        "providers_queried": "[]", "query_count": 0,
                        "discovery_ok": False, "exec_out": True}
        elif plan_json.strip():
            try:
                plan = json.loads(plan_json)
                queries = plan.get("asset_queries", []) if isinstance(plan, dict) else []
            except Exception as exc:
                self.log_error(f"Failed to parse scene_plan_json: {exc}")
                return {"discovery_result_json": "{}", "total_assets": 0,
                        "providers_queried": "[]", "query_count": 0,
                        "discovery_ok": False, "exec_out": True}

        if not queries:
            self.log_error("No asset queries found in scene_plan_json or asset_queries_json.")
            return {"discovery_result_json": "{}", "total_assets": 0,
                    "providers_queried": "[]", "query_count": 0,
                    "discovery_ok": False, "exec_out": True}

        try:
            result = get_asset_discovery_engine().discover(queries, limit_per_provider=limit)
            self.log_info(
                f"Discovery: {result.total_assets} assets across "
                f"{len(result.query_results)} queries, "
                f"providers={result.providers_queried}"
            )
            return {
                "discovery_result_json": json.dumps(result.to_dict(), default=str),
                "total_assets":          result.total_assets,
                "providers_queried":     json.dumps(result.providers_queried),
                "query_count":           len(result.query_results),
                "discovery_ok":          result.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Asset discovery failed: {exc}")
            return {"discovery_result_json": "{}", "total_assets": 0,
                    "providers_queried": "[]", "query_count": 0,
                    "discovery_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Discover
